 /** Selects paths with an ordered list of glob patterns. See README.md for the syntax. */
 export class PathMatcher {
+  private readonly patterns: string[];
+
   constructor(patterns: string[]) {
-    throw new Error("not implemented");
+    this.patterns = [...patterns];
   }

   /** Whether `path` is selected. */
   matches(path: string): boolean {
-    throw new Error("not implemented");
+    return this.explain(path) !== null;
   }

   /** The selected paths, in their original order. */
   filter(paths: string[]): string[] {
-    throw new Error("not implemented");
+    return paths.filter((path) => this.matches(path));
   }

   /** The pattern that decided about `path`, or null when none matches. */
   explain(path: string): string | null {
-    throw new Error("not implemented");
+    let matchedPattern: string | null = null;
+
+    for (const pattern of this.patterns) {
+      if (pattern.startsWith('!')) {
+        const negatedPattern = pattern.slice(1);
+        if (this.matchPattern(negatedPattern, path)) {
+          matchedPattern = pattern;
+        }
+      } else {
+        if (this.matchPattern(pattern, path)) {
+          matchedPattern = pattern;
+        }
+      }
+    }
+
+    // Return null if no pattern matched or if the last matching pattern was a negation
+    if (matchedPattern === null || matchedPattern.startsWith('!')) {
+      return null;
+    }
+
+    return matchedPattern;
+  }
